export interface RuleThing {
  /** Its place in the engine's list: how a RULES lump names it. */
  index: number;
  /** The engine's name for it. */
  id: string;
  /** The number a level names it by, or -1 if it is never placed in one. */
  number: number;
  /** The sprite it stands as. */
  sprite: string;
  sort: "monster" | "shot" | "pickup" | "player" | "scenery";
  /** Where its moments start, by their place in the engine's list: 0 is none. */
  spawnstate: number;
  seestate: number;
  painstate: number;
  meleestate: number;
  missilestate: number;
  deathstate: number;
  xdeathstate: number;
  raisestate: number;
  health: number;
  speed: number;
  radius: number;
  height: number;
  mass: number;
  damage: number;
  painchance: number;
  reaction: number;
  /** Its sounds, by their lumps' names; "" for none. */
  seesound: string;
  attacksound: string;
  painsound: string;
  deathsound: string;
  activesound: string;
}

